assignments.value:
={{
  $('Set - Preparar Evaluacion').item.json.arquitectura === 'A'
    ? $('Set - Candidato A').item.json.respuesta_candidata
    : $('Set - Candidato B').item.json.respuesta_candidata
}}

={{
  String($('Set - Resultado Juez 1').item.json.arquitectura).trim().toUpperCase() === 'A'
    ? 4
    : String($('Set - Resultado Juez 1').item.json.arquitectura).trim().toUpperCase() === 'B'
      ? 5
      : 0
}}

